steps.script:
var p = PhaseManager.get_current_phase_instance()
for i in range(4):
	if p == null or not p.has_pending_stratagem_window():
		break
	var w = p.get_pending_stratagem_window()
	if str(w.get("window_id", "")) != "movement_phase_start":
		break
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
return p != null and not p.has_pending_stratagem_window()

var out = []
for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		for c in t.find_children("*", "Label", true, false):
			out.append(c.text)
return " | ".join(out).contains("Rapid Ingress: Caladius Grav-tank arrived!")

var p = PhaseManager.get_current_phase_instance()
if p == null or not p.has_pending_stratagem_window():
	return "none"
var w = p.get_pending_stratagem_window()
var ids := []
for o in w.get("offers", []):
	ids.append(str(o.get("stratagem_id", "")))
return "P%d %s: %s" % [int(w.get("player", 0)), str(w.get("window_id", "")), ",".join(ids)]

var p = PhaseManager.get_current_phase_instance()
var w = p.get_pending_stratagem_window()
NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": 2, "window_id": str(w.get("window_id", ""))})
return true
